```c
// Original netc_xmit_ntmp_cmd timeout handling:
if (unlikely(err))
    goto cbdr_unlock;
...
cbdr_unlock:
    spin_unlock_bh(&cbdr->ring_lock);
    return err;

// Caller unconditionally frees DMA buffer after command:
err = netc_xmit_ntmp_cmd(user, &cbd);
